// @FIGURE_CODE_BEGIN
// ELEMENT SPEC
// tree trunk    → CylinderGeometry tapered #8b5a2b + 2 TubeGeometry curved branches
// canopy        → 7 SphereGeometry blobs, greens #7fff00 / #3cc61e / #228b22
// wall          → PlaneGeometry 6x5 white at x=-5 facing +X, black border lines, label 'Wall'
// barrier       → ShapeGeometry 6x5 black with circular hole at world (0,1.5,0), label 'Pinhole' + white dot
// fan rays      → THREE.Line green/brown from scene pts to 2 wall targets (no-aperture mode)
// pinhole rays  → THREE.Line from scene pts through hole to wall (pinhole mode)
// projected img → additive Sprites pale #c8f7a0 / #d9c8b0, radius/alpha scale with pinholeSize
// highlight     → yellow lines + glowing sprite for clicked wall point
// arrowheads    → small ConeGeometry at ray ends

scene.add(new THREE.AmbientLight(0xffffff, 0.9));
const dl = new THREE.DirectionalLight(0xffffff, 0.9); dl.position.set(3, 8, 6); scene.add(dl);

const HOLE = new THREE.Vector3(0, 1.5, 0);

/* ── Tree ── */
const tree = new THREE.Group(); scene.add(tree);
const trunkMat = new THREE.MeshStandardMaterial({ color: 0x8b5a2b, roughness: 0.9 });
const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.38, 2.2, 12), trunkMat);
trunk.position.set(5, 1.1, 0); tree.add(trunk);
function branch(a, b, c) {
  const curve = new THREE.QuadraticBezierCurve3(a, b, c);
  return new THREE.Mesh(new THREE.TubeGeometry(curve, 12, 0.09, 8), trunkMat);
}
tree.add(branch(new THREE.Vector3(5, 1.7, 0), new THREE.Vector3(4.3, 2.3, 0.1), new THREE.Vector3(4.1, 2.8, 0.3)));
tree.add(branch(new THREE.Vector3(5, 1.8, 0), new THREE.Vector3(5.8, 2.4, -0.2), new THREE.Vector3(6.1, 2.9, -0.4)));
const canopyCols = [0x7fff00, 0x3cc61e, 0x228b22];
const canopySpec = [
  [5.2, 3.4, 0.3, 1.2, 0], [4.5, 3.0, -0.4, 1.0, 0], [5.7, 2.7, 0.6, 1.1, 1],
  [4.8, 2.3, 0.1, 0.9, 0], [5.1, 3.9, -0.3, 1.0, 1], [5.9, 3.5, -0.6, 0.9, 2],
  [4.3, 3.6, 0.7, 0.85, 2]
];
for (const [x, y, z, r, ci] of canopySpec) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, 20, 16),
    new THREE.MeshStandardMaterial({ color: canopyCols[ci], roughness: 0.8 }));
  m.position.set(x, y, z); tree.add(m);
}

/* ── Scene sample points (green = canopy, brown = trunk) ── */
const scenePts = [
  { p: new THREE.Vector3(5.2, 3.6, 0.3), c: 0x39d400, pale: 0xc8f7a0 },
  { p: new THREE.Vector3(4.5, 3.1, -0.3), c: 0x39d400, pale: 0xc8f7a0 },
  { p: new THREE.Vector3(5.7, 2.8, 0.5), c: 0x39d400, pale: 0xc8f7a0 },
  { p: new THREE.Vector3(5.0, 2.4, 0.1), c: 0x39d400, pale: 0xc8f7a0 },
  { p: new THREE.Vector3(5.1, 3.9, -0.2), c: 0x39d400, pale: 0xc8f7a0 },
  { p: new THREE.Vector3(5.0, 1.6, 0.0), c: 0x8b5a2b, pale: 0xd9c8b0 },
  { p: new THREE.Vector3(5.0, 0.7, 0.0), c: 0x8b5a2b, pale: 0xd9c8b0 },
  { p: new THREE.Vector3(4.6, 2.0, 0.15), c: 0x8b5a2b, pale: 0xd9c8b0 },
  { p: new THREE.Vector3(5.5, 2.0, -0.15), c: 0x8b5a2b, pale: 0xd9c8b0 },
];
const wallTargets = [new THREE.Vector3(-5, 1.0, 0.2), new THREE.Vector3(-5, 2.5, -0.2)];

/* ── Wall ── */
const wallGroup = new THREE.Group(); scene.add(wallGroup);
const wallMesh = new THREE.Mesh(new THREE.PlaneGeometry(6, 5),
  new THREE.MeshBasicMaterial({ color: 0xffffff }));
wallMesh.rotation.y = Math.PI / 2; wallMesh.position.set(-5, 2.5, 0); wallGroup.add(wallMesh);
{
  const e = new THREE.EdgesGeometry(wallMesh.geometry);
  const border = new THREE.LineSegments(e, new THREE.LineBasicMaterial({ color: 0x000000 }));
  border.rotation.y = Math.PI / 2; border.position.copy(wallMesh.position); wallGroup.add(border);
}

/* ── Barrier (rebuilt when pinhole size changes) ── */
const pinGroup = new THREE.Group(); scene.add(pinGroup);
let barrierMesh = null, holeDot = null;
function buildBarrier(size) {
  if (barrierMesh) { pinGroup.remove(barrierMesh); barrierMesh.geometry.dispose(); }
  if (holeDot) { pinGroup.remove(holeDot); holeDot.geometry.dispose(); }
  const r = 0.5 * size;
  const shape = new THREE.Shape();
  shape.moveTo(-3, -2.5); shape.lineTo(3, -2.5); shape.lineTo(3, 2.5); shape.lineTo(-3, 2.5); shape.closePath();
  const hole = new THREE.Path(); hole.absarc(0, -1.0, r, 0, Math.PI * 2, true);
  shape.holes.push(hole);
  barrierMesh = new THREE.Mesh(new THREE.ShapeGeometry(shape, 24),
    new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.DoubleSide, transparent: true }));
  barrierMesh.rotation.y = Math.PI / 2; barrierMesh.position.set(0, 2.5, 0);
  pinGroup.add(barrierMesh);
  holeDot = new THREE.Mesh(new THREE.CircleGeometry(Math.max(r * 0.55, 0.05), 20),
    new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide, transparent: true }));
  holeDot.rotation.y = Math.PI / 2; holeDot.position.set(0.01, 1.5, 0);
  pinGroup.add(holeDot);
  pinholeMats = [];
  pinGroup.traverse(o => { if (o.material) pinholeMats.push(o.material); });
}

/* ── Fade groups ── */
let fanMats = [], pinholeMats = [];
const fanState = { cur: 1, target: 1 };
const pinState = { cur: 0, target: 0 };

/* ── Rays ── */
function makeRay(a, b, color) {
  const g = new THREE.Group();
  const mat = new THREE.LineBasicMaterial({ color, transparent: true });
  const dir = b.clone().sub(a).normalize();
  const end = b.clone().sub(dir.clone().multiplyScalar(0.14));
  g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([a, end]), mat));
  const coneMat = new THREE.MeshBasicMaterial({ color, transparent: true });
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.16, 8), coneMat);
  cone.position.copy(b.clone().sub(dir.clone().multiplyScalar(0.07)));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  g.add(cone);
  g.userData.mats = [mat, coneMat];
  return g;
}

const fanGroup = new THREE.Group(); scene.add(fanGroup);
scenePts.forEach((s, i) => {
  const t = wallTargets[i % 2];
  fanGroup.add(makeRay(s.p, t, s.c));
});
fanGroup.traverse(o => { if (o.userData.mats) fanMats.push(...o.userData.mats); });

const pinRayGroup = new THREE.Group(); pinGroup.add(pinRayGroup);
function wallPointFrom(sp) { // line scene→hole extended to wall x=-5
  const u = (-5 - sp.x) / (HOLE.x - sp.x);
  return new THREE.Vector3(-5, sp.y + u * (HOLE.y - sp.y), sp.z + u * (HOLE.z - sp.z));
}
for (const s of scenePts) pinRayGroup.add(makeRay(s.p, wallPointFrom(s.p), s.c));

/* ── Glow sprite texture ── */
function glowTexture() {
  const cv = document.createElement('canvas'); cv.width = cv.height = 64;
  const ctx = cv.getContext('2d');
  const g = ctx.createRadialGradient(32, 32, 2, 32, 32, 32);
  g.addColorStop(0, 'rgba(255,255,255,1)'); g.addColorStop(0.5, 'rgba(255,255,255,0.5)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(cv);
}
const glowTex = glowTexture();

/* ── Projected image sprites (pinhole mode) ── */
const imgSprites = [];
for (const s of scenePts) {
  const wp = wallPointFrom(s.p);
  const sm = new THREE.SpriteMaterial({
    map: glowTex, color: s.pale, transparent: true,
    blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.3
  });
  const sp = new THREE.Sprite(sm);
  sp.position.set(-4.93, wp.y, wp.z);
  pinGroup.add(sp); imgSprites.push(sp);
}

/* ── Wall target dots (fan mode) ── */
for (const t of wallTargets) {
  const sm = new THREE.SpriteMaterial({ map: glowTex, color: 0xaaff66, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false });
  const sp = new THREE.Sprite(sm); sp.position.set(-4.93, t.y, t.z); sp.scale.setScalar(0.9);
  fanGroup.add(sp); fanMats.push(sm);
}

/* ── Highlight (wall click) ── */
const hlGroup = new THREE.Group(); scene.add(hlGroup);
function clearHighlight() { while (hlGroup.children.length) { const c = hlGroup.children.pop(); hlGroup.remove(c); } }
function highlightWallPoint(wp) {
  clearHighlight();
  const dot = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex, color: 0xffee33, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false }));
  dot.position.set(-4.9, wp.y, wp.z); dot.scale.setScalar(0.8); hlGroup.add(dot);
  if (pinState.target > 0.5) {
    const sy = 2 * HOLE.y - wp.y, sz = -wp.z;
    hlGroup.add(makeRay(new THREE.Vector3(5, sy, sz), new THREE.Vector3(-5, wp.y, wp.z), 0xffdd00));
  } else {
    for (const s of scenePts) hlGroup.add(makeRay(s.p, new THREE.Vector3(-5, wp.y, wp.z), 0xffdd00));
  }
}
const _rc = new THREE.Raycaster(), _pv = new THREE.Vector2();
canvas.addEventListener('click', (e) => {
  const r = canvas.getBoundingClientRect();
  _pv.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  _pv.y = -((e.clientY - r.top) / r.height) * 2 + 1;
  _rc.setFromCamera(_pv, camera);
  const hits = _rc.intersectObject(wallMesh);
  if (hits.length) {
    const p = hits[0].point;
    highlightWallPoint(new THREE.Vector3(-5, Math.max(0.2, Math.min(4.8, p.y)), Math.max(-2.8, Math.min(2.8, p.z))));
  }
});
registerInteractive(wallMesh, {
  title: 'Wall (image plane)',
  tooltip: 'Click: see which rays light this point',
  body: 'Without a pinhole this point receives rays from many scene directions at once — no image. With a pinhole only one direction reaches it, giving a one-to-one scene-to-image mapping.'
});

/* ── State / tween ── */
let pinholeSize = 0.3;
buildBarrier(pinholeSize);
function applyPinholeSize() {
  buildBarrier(pinholeSize);
  const r = 0.35 + 0.6 * pinholeSize;
  const a = Math.min(1, 0.22 + 0.35 * pinholeSize);
  for (const sp of imgSprites) { sp.scale.setScalar(2 * r); sp.userData.baseAlpha = a; }
  // fade bookkeeping: rebuild barrier reset materials — reapply current fade
  pinGroup.traverse(o => { if (o.userData.mats) pinholeMats.push(...o.userData.mats); });
  applyFades();
}
function applyFades() {
  for (const m of fanMats) m.opacity = fanState.cur;
  for (const m of pinholeMats) m.opacity = pinState.cur;
  for (const sp of imgSprites) sp.material.opacity = (sp.userData.baseAlpha || 0.3) * pinState.cur;
  fanGroup.visible = fanState.cur > 0.02;
  pinGroup.visible = pinState.cur > 0.02;
}
(function fadeLoop() {
  requestAnimationFrame(fadeLoop);
  let dirty = false;
  for (const st of [fanState, pinState]) {
    if (Math.abs(st.cur - st.target) > 0.004) { st.cur += (st.target - st.cur) * 0.12; dirty = true; }
  }
  if (dirty) applyFades();
})();

const panelLbl = addLabel('(a) No aperture', new THREE.Vector3(-1, -0.35, 0), { bold: true, fontSize: '15px' });
addLabel('Wall', new THREE.Vector3(-5, 5.3, 0), { bold: true, fontSize: '16px' });
const pinLbl = addLabel('Pinhole', new THREE.Vector3(0, 5.3, 0), { bold: true, fontSize: '16px' });

function setMode(pin) {
  fanState.target = pin ? 0 : 1;
  pinState.target = pin ? 1 : 0;
  panelLbl.div.innerHTML = pin ? '(b) Pinhole' : '(a) No aperture';
  pinLbl.div.style.display = pin ? '' : 'none';
  document.getElementById('btnNoAp').classList.toggle('active', !pin);
  document.getElementById('btnPin').classList.toggle('active', pin);
  clearHighlight();
}
