tree.add(branch(new THREE.Vector3(5, 1.7, 0), new THREE.Vector3(4.3, 2.3, 0.1), new THREE.Vector3(4.1, 2.8, 0.3)));
tree.add(branch(new THREE.Vector3(5, 1.8, 0), new THREE.Vector3(5.8, 2.4, -0.2), new THREE.Vector3(6.1, 2.9, -0.4)));
const canopyCols = [0x7fff00, 0x3cc61e, 0x228b22];
const canopySpec = [
  [5.2, 3.4, 0.3, 1.2, 0], [4.5, 3.0, -0.4, 1.0, 0], [5.7, 2.7, 0.6, 1.1, 1],
  [4.8, 2.3, 0.1, 0.9, 0], [5.1, 3.9, -0.3, 1.0, 1], [5.9, 3.5, -0.6, 0.9, 2],
